import{_ as t,o as a,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"售后工单 Agent","description":"项目契约：实现能够查询订单、选择售后方案、请求确认并幂等执行业务动作的工具型 Agent。","frontmatter":{"title":"售后工单 Agent","description":"项目契约：实现能够查询订单、选择售后方案、请求确认并幂等执行业务动作的工具型 Agent。","article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"py-agent/architecture/projects/aftersales-ticket-agent.md","filePath":"py-agent/architecture/projects/aftersales-ticket-agent.md","lastUpdated":null}'),l={name:"py-agent/architecture/projects/aftersales-ticket-agent.md"};function n(o,e,s,c,d,p){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="售后工单-agent" tabindex="-1">售后工单 Agent <a class="header-anchor" href="#售后工单-agent" aria-label="Permalink to &quot;售后工单 Agent&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本项目类型为 <strong>工具型 Agent</strong>。核心不是让模型自由处理退款，而是让模型在受控工具、业务规则和确认边界内完成售后工单。</p><h2 id="项目结果" tabindex="-1">项目结果 <a class="header-anchor" href="#项目结果" aria-label="Permalink to &quot;项目结果&quot;">​</a></h2><p>读者最终会得到一个售后服务 API：Agent 能查询订单和物流，识别用户诉求，提出补发、补偿或退款方案；涉及外部副作用时先返回确认请求，确认后使用幂等键执行并记录审计事件。</p><h2 id="实现范围" tabindex="-1">实现范围 <a class="header-anchor" href="#实现范围" aria-label="Permalink to &quot;实现范围&quot;">​</a></h2><ul><li>LangChain Agent 负责意图理解、工具选择和结构化结果；</li><li>工具分别封装订单查询、物流查询、工单创建和补偿执行；</li><li>Middleware 注入租户、用户、权限、预算和 Trace 上下文；</li><li>PostgreSQL 保存订单快照、工单、审计事件和带唯一幂等键的执行账本；</li><li>Redis 保存短期会话、限流状态和短期协调锁，不作为执行结果的权威来源；</li><li>FastAPI 暴露会话、确认、取消和工单查询接口；</li><li>测试覆盖错误工具参数、重复确认、超时、越权订单和部分失败。</li></ul><h2 id="验收基线" tabindex="-1">验收基线 <a class="header-anchor" href="#验收基线" aria-label="Permalink to &quot;验收基线&quot;">​</a></h2><p>项目必须证明同一个确认请求最多产生一次业务副作用，并能从 Trace 中还原模型为何选择某个工具。支付通道和真实电商平台使用本地适配器模拟，但接口、错误和幂等语义必须完整。</p>',9)])])}const u=t(l,[["render",n]]);export{g as __pageData,u as default};
